import numpy as np
from scipy.optimize import minimize

try:
    from pyDOE2 import lhs as _lhs
except ImportError:
    try:
        from scipy.stats import qmc
        def _lhs(n_samples, n_dim):
            return qmc.LatinHypercube(d=n_dim).random(n=n_samples)
    except ImportError:
        raise ImportError("pyDOE2 or scipy required")

class Optimizer:
    def __init__(self, budget: int, dim: int):
        self.budget = budget
        self.dim = dim
        self.evals = 0
        self.best_f = float('inf')
        self.best_x = np.zeros(dim)
        self.rng = np.random.default_rng(42)
        self.stag = 0
        self.cat_archive = []
        self.temp = 1.0
        self.cont_div = 1.0
        self.cat_div = 1.0

    def _evaluate(self, x, func):
        if self.evals >= self.budget: return float('inf')
        xc = np.clip(x, -1.0, 1.0)
        f = func(xc)
        self.evals += 1
        if f < self.best_f:
            self.best_f = f
            self.best_x = xc.copy()
        return f

    def _update_diversity(self, pop):
        self.cont_div = np.std(pop[:, :18], axis=0).mean()
        self.cat_div = np.std(pop[:, 18:], axis=0).mean()

    def _biased_cat_sample(self, n):
        if len(self.cat_archive) == 0:
            return self.rng.uniform(-1.0, 1.0, (n, 6))
        inv_temp = 1.0 / max(self.temp, 1e-4)
        scores = np.exp(inv_temp * np.linalg.norm(self.cat_archive - self.best_x[18:], axis=1))
        probs = scores / np.sum(scores)
        idxs = self.rng.choice(len(self.cat_archive), size=n, p=probs)
        noise = self.rng.normal(0, np.clip(0.12 * self.temp, 0.01, 0.35), (n, 6))
        return self.cat_archive[idxs] + noise

    def __call__(self, func, grad_func=None):
        if self.evals >= self.budget: return self.best_f, self.best_x

        n_pop = max(10, min(50, self.budget // 4))
        pop = _lhs(n_samples=n_pop, n_dim=24)
        pop = np.clip(pop * 2.0 - 1.0, -1.0, 1.0)
        pop[:, 18:] = self._biased_cat_sample(n_pop)
        self._update_diversity(pop)

        fitness = np.array([self._evaluate(p, func) for p in pop])
        valid_mask = np.isfinite(fitness)
        max_gen = min(30, max(3, self.budget // n_pop))

        grad_w = 1.0
        improvement_rate = 0.95

        for gen in range(max_gen):
            if self.evals >= self.budget: break

            f_valid = fitness[valid_mask]
            if len(f_valid) > 2:
                improvement_rate = 0.95 if gen > 0 else 1.0
                f_scale = np.clip(self.cont_div / 0.3, 0.2, 1.0)
                CR = np.clip(0.5 + 0.4 * (1.0 - improvement_rate), 0.1, 0.9)
            else:
                f_scale, CR = 1.0, 0.9

            best_idx = np.argmin(fitness)
            x_best = pop[best_idx]
            g_bias = np.zeros(24)

            if grad_func:
                try:
                    g = grad_func(x_best)
                    if g is not None and len(g) == 18:
                        g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                        norm_g = np.linalg.norm(g_c) + 1e-8
                        g_bias[:18] = (g_c / norm_g) * 0.05 * grad_w
                        cat_step = np.clip(0.05 + 0.1 * np.mean(np.abs(g_c)), 0.03, 0.25)
                        self.temp = np.clip(0.8 - 0.3 * (np.min(f_valid) / (np.mean(f_valid) + 1e-8)), 0.1, 1.0)
                except Exception: pass

            is_low_div = self.cont_div < 0.1 or self.cat_div < 0.1
            if is_low_div:
                self.stag += 1
            else:
                self.stag = 0

            for i in range(n_pop):
                if self.evals >= self.budget: break

                idxs = self.rng.choice(n_pop, 3, replace=False)
                while np.any(idxs == i): idxs = self.rng.choice(n_pop, 3, replace=False)

                base_F = np.clip(self.rng.uniform(0.4, 0.9), 0.1, 1.0)
                F = base_F * f_scale if not is_low_div else base_F * 1.5

                if self.rng.random() < 0.5:
                    v = pop[i] + F * (pop[idxs[0]] + pop[idxs[1]] - 2 * x_best)
                else:
                    v = x_best + F * (pop[idxs[0]] - pop[idxs[1]])

                v += g_bias

                if is_low_div or self.rng.random() < 0.1:
                    cat_noise = self.rng.cauchy(0, 0.15, 6) * f_scale
                else:
                    cat_noise = self.rng.normal(0, cat_step, 6)
                v[18:] += cat_noise
                v[:18] += self.rng.standard_normal(18) * 0.01 * f_scale

                trial = np.clip(v, -1.0, 1.0)
                f_trial = self._evaluate(trial, func)

                if np.isinf(f_trial) and self.evals < self.budget:
                    if grad_func:
                        try:
                            g = grad_func(trial)
                            if g is not None:
                                g_c = np.nan_to_num(g, nan=0.0, posinf=0.0, neginf=0.0)
                                push_dir = np.concatenate([g_c, np.zeros(6)]) + 1e-8
                                push_dir = push_dir / np.linalg.norm(push_dir) * 0.15
                                trial = np.clip(trial + push_dir, -1.0, 1.0)
                                f_trial = self._evaluate(trial, func)
                        except Exception: pass
                    if np.isinf(f_trial):
                        trial[18:] = np.clip(trial[18:] + self.rng.cauchy(0, 0.3, 6), -1.0, 1.0)
                        f_trial = self._evaluate(trial, func)

                if np.isfinite(f_trial):
                    delta = fitness[i] - f_trial
                    accept_prob = 1.0 if delta > 0 else np.exp(delta / max(self.temp, 1e-4))
                    if self.rng.random() < accept_prob:
                        pop[i] = trial
                        fitness[i] = f_trial
                        if f_trial < self.best_f:
                            self.best_f = f_trial
                            self.best_x = trial.copy()
                        self.cat_archive.append(trial[18:].copy())
                        if len(self.cat_archive) > 40: self.cat_archive.pop(0)
                elif np.isfinite(fitness[i]):
                    pop[i] = trial
                    fitness[i] = f_trial
                    if np.isfinite(f_trial):
                        self.cat_archive.append(trial[18:].copy())
                        if len(self.cat_archive) > 40: self.cat_archive.pop(0)
                else:
                    self.stag += 1

            self._update_diversity(pop)
            grad_w *= 0.98
            self.temp *= 0.98

        if self.evals < self.budget * 0.85 and grad_func:
            remaining = int(self.budget * 0.1)
            if remaining < 10: remaining = 10
            top_idx = np.argsort(fitness)[:min(5, n_pop)]
            evals_per_run = max(1, remaining // max(len(top_idx), 1))

            for idx in top_idx:
                if self.evals >= self.budget * 0.85: break
                x0_c = pop[idx][:18]
                cats = pop[idx][18:]

                def cost_wrap(x_c, _cats=cats): return self._evaluate(np.concatenate([x_c, _cats]), func)
                def grad_wrap(x_c, _cats=cats):
                    full = np.concatenate([x_c, _cats])
                    try:
                        g = grad_func(full)
                        return np.nan_to_num(g[:18], nan=0.0, posinf=0.0, neginf=0.0) if g is not None else np.zeros(18)
                    except Exception:
                        return np.zeros(18)

                res = minimize(cost_wrap, x0_c, jac=grad_wrap, method='L-BFGS-B',
                               bounds=[(-1.0, 1.0)]*18,
                               options={'maxiter': evals_per_run, 'ftol': 1e-10, 'gtol': 1e-9})
                if np.isfinite(res.fun) and res.fun < self.best_f:
                    self.best_f = res.fun
                    self.best_x = np.concatenate([res.x, cats])

        return self.best_f, self.best_x
